import{z as n,x as p,o as t,c as A,q as l,j as o,D as e,d as E,s,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"复制延迟与读己之写","description":"","frontmatter":{"title":"复制延迟与读己之写","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/replication-lag-rmw.md","filePath":"cs/replication-lag-rmw.md","lastUpdated":1791063341000}'),d={name:"cs/replication-lag-rmw.md"};function m(c,a,D,u,h,S){const B=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=l('<h1 id="复制延迟与读己之写" tabindex="-1">复制延迟与读己之写 <a class="header-anchor" href="#复制延迟与读己之写" aria-label="Permalink to &quot;复制延迟与读己之写&quot;">​</a></h1><div class="epigraph"><p>写主读备时，用户可能读不到刚写的行。读己之写是会话合同，不是隔离级别自带的礼物。</p><footer>—— 据 Bailis et al. 对会话保证；Gray 复制；半同步对照</footer></div><p><a href="/cs/semi-sync-replication">上一课</a>让提交等备库。本课即使 ACK 了 apply 仍可能落后，异步更甚。事务进阶在此封口。缺口是会话：应用写主后立刻读备，看见旧快照。主干复制课点到延迟；进阶钉 <strong>read-your-writes</strong> 及常见补丁（粘滞、等 LSN、只读走主）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>隔离级别描述单副本上的并发。多副本上，因果与会话要另写。读己之写：同一客户端写提交后，其后续读应看见该写（或更新）。单调读：不回到更旧快照。缺口是备库 apply 落后于主的提交 LSN。</p><p>半同步保证备库<strong>收到</strong>，不保证<strong>已 apply</strong>，更不保证<strong>你的下一次读打到该备</strong>。负载均衡随机备库会打破单调读。</p><p><span class="marginnote">会话保证文献（read-your-writes、monotonic reads）。本课工程补丁。分布式数据库课会把因果与 TrueTime 再升级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写后读主：简单，备库只承担落后只读。会话粘滞：同一会话钉同一备，并记录主上 <code>commit_lsn</code>，读前等备库 <code>replay &gt;= lsn</code>（或超时走主）。令牌：把 LSN 放进用户 cookie。</p><p>CDC 下游更滞后，不能当读己之写存储除非等。</p><p><span class="marginnote">数字实例：主上写入返回的 commit LSN 是 900，某备库刚 replay 到 850，落后 50 条记录。应用带着 LSN=900 来读时，正确做法是先问备库「你到多少了」，850 \\lt 900 就再等几毫秒，而不是直接把 850 时点的快照端给用户——旧值就是从这 50 条差里漏出去的。</span></p><p><span class="marginnote">直觉类比：commit LSN 像快递单号，备库 replay 像包裹签收进度。「读己之写」就是寄出后想查件时，必须确认物流已显示「本人签收」（replay \\gt 单号），而不是随机拨一家快递网点问——不同网点的进度牌不同，问错了就会被告知「还没寄出」。</span></p>',12)),(t(),o(i,null,{default:e(()=>[s(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E4%B8%BB%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20LSN%5B%22%E8%AE%B0%E4%B8%8B%20commit%20LSN%22%5D%0A%20%20R%5B%22%E8%AF%BB%22%5D%20--%3E%20WAIT%5B%22%E5%A4%87%E5%BA%93%20replay%20%E8%BF%BD%E4%B8%8A%22%5D%0A%20%20R%20--%3E%20MASTER%5B%22%E6%88%96%E8%AF%BB%E4%B8%BB%22%5D%0A%20%20LB%5B%22%E9%9A%8F%E6%9C%BA%E5%A4%87%E5%BA%93%22%5D%20--%3E%20BRK%5B%22%E6%89%93%E7%A0%B4%E5%8D%95%E8%B0%83%E8%AF%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"连接池：还池丢会话粘滞则保证碎——连接池课的状态泄漏在复制层重现。只读事务快照若取自落后备库，分析一致但是陈旧，要标 SLA。",-1)),a[5]||(a[5]=r("p",null,"故障：等 LSN 超时应失败可见，不能悄悄返回旧行当成功。",-1)),(t(),o(i,null,{default:e(()=>[s(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E6%94%B9%E4%BA%86%E5%A4%B4%E5%83%8F%2C%20%E7%AB%8B%E5%8D%B3%E5%88%B7%E6%96%B0%E9%A1%B5%E9%9D%A2%22%5D%20--%3E%20G%5B%22%E8%AF%B7%E6%B1%82%E5%B8%A6%20commit%20LSN%3D900%22%5D%0A%20%20G%20--%3E%20LB%7B%22%E8%B4%9F%E8%BD%BD%E5%9D%87%E8%A1%A1%E9%80%89%E4%BA%86%E8%B0%81%3F%22%7D%0A%20%20LB%20--%20%22%E9%9A%8F%E6%9C%BA%E5%A4%87%E5%BA%93(replay%3D850)%22%20--%3E%20OLD%5B%22%E7%9C%8B%E5%88%B0%E6%97%A7%E5%A4%B4%E5%83%8F%3A%20%E8%BF%9D%E5%8F%8D%E8%AF%BB%E5%B7%B1%E4%B9%8B%E5%86%99%22%5D%0A%20%20LB%20--%20%22%E7%B2%98%E6%BB%9E%E4%BC%9A%E8%AF%9D%3A%20%E7%AD%89%E5%A4%87%E5%BA%93%E8%BF%BD%E4%B8%8A%E6%88%96%E8%B5%B0%E4%B8%BB%22%20--%3E%20NEW%5B%22%E7%9C%8B%E5%88%B0%E6%96%B0%E5%A4%B4%E5%83%8F%22%5D%0A%20%20OLD%20-.%E4%BF%AE%E5%A4%8D.-%3E%20NEW%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>这张图回答的问题是「同一个用户刚写完立刻读，旧值从哪条路径漏出来」：漏点不在数据库内部，而在负载均衡的随机选备——每次读都可能落到 replay 进度不同的备库，单调读也随之破碎。修复靠会话粘滞或 LSN 门闩，不靠调大延迟容忍。</p><p><span class="marginnote">为什么重要：这一步如果做错了（超时后仍返回旧行），用户会形成「改了又没改」的诡异体验，且因为只在高峰延迟大时偶发，极难定位。正确姿势是把超时变成显式错误或降级读主，让应用层知道这次读不可信。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲分片键。也不把读己之写当线性一致。恢复复制续结束：从 ARIES 到会话读。</p><p>后课默认：读备库要会话合同；默认教学写后读主。下一课程分布式：分片键与再平衡，故障域变成多主存储。</p><p>延迟是复制的物理；会话保证是应用看见的逻辑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>读备库需显式读己之写：等 LSN、粘滞或读主。</li><li>随机负载均衡破坏单调读；池必须带会话状态。</li><li>下一课程分片键与再平衡。</li><li>出处：会话保证文献；Gray；复制实践。</li></ul>',8))])}const f=n(d,[["render",m]]);export{g as __pageData,f as default};
